import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices with future due dates', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2026-10-20');
  assert.equal(result.length, 0);
});

test('overdueInvoices includes invoices with past due dates', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices excludes invoices due on asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2026-10-31');
  assert.equal(result.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2026-10-25');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const result = overdueInvoices([inv], '2026-10-20');
  assert.equal(result.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-20' }).value;

  const result = overdueInvoices([paid], '2026-10-25');
  assert.equal(result.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partially_paid = recordPayment(issued, { amount: 5000, date: '2026-10-20' }).value;

  const result = overdueInvoices([partially_paid], '2026-10-25');
  assert.equal(result.length, 1);
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices includes customerId in result', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].customerId, 'C-003');
});

test('overdueInvoices includes dueDate in result', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].dueDate, '2026-10-15');
});

test('overdueInvoices calculates due amount for unpaid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const result = overdueInvoices([issued], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices calculates due amount for partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partially_paid = recordPayment(issued, { amount: 5000, date: '2026-10-20' }).value;

  const result = overdueInvoices([partially_paid], '2026-10-25');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - 5000);
});

test('overdueInvoices sorts by most overdue first', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = overdueInvoices([issued2, issued1], '2026-10-25');
  assert.equal(result.length, 2);
  assert.equal(result[0].dueDate, '2026-09-15');
  assert.equal(result[1].dueDate, '2026-10-15');
  assert.equal(result[0].daysOverdue, 40);
  assert.equal(result[1].daysOverdue, 10);
});

test('overdueInvoices with mixed invoice statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const draft = inv1;
  const issued = issueInvoice(inv2, []).value;

  const result = overdueInvoices([draft, issued], '2026-10-25');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices with multiple overdue invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-20',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  const result = overdueInvoices([issued1, issued2, issued3], '2026-10-25');
  assert.equal(result.length, 3);
  assert.equal(result[0].daysOverdue, 26);
  assert.equal(result[1].daysOverdue, 21);
  assert.equal(result[2].daysOverdue, 10);
});

test('overdueInvoices on EOM term', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2026-11-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].dueDate, '2026-10-31');
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices returns empty when all invoices are in future', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-11-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-11-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
